    /**
     * Tests getting all PlannedOrders.
     *
     * @return    Collection
     */
    public List<PlannedOrder> testGetAll() throws Throwable {
    LOGGER.info( "PlannedOrderTest:testGetAll() - Retrieving Collection of PlannedOrders:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all PlannedOrder : " );
    List<PlannedOrder> collection  = null;

    try {
        // call the static get method on the PlannedOrderService
        collection = service.getAllPlannedOrder();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            PlannedOrder currEntity  = null;
            Iterator<PlannedOrder> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getPlannedOrderId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

